record_usage:
function record_usage(key, model, tokens) {
  if (typeof key !== "string" || key === "") {
    throw new Error("key must be a non-empty string");
  }
  if (typeof model !== "string" || model === "") {
    throw new Error("model must be a non-empty string");
  }
  if (typeof tokens !== "number" || !isFinite(tokens) || tokens <= 0 || tokens % 1 !== 0) {
    throw new Error("tokens must be a positive whole number");
  }
  const quotas = state.quotas || {};
  const quota = quotas[key];
  if (typeof quota === "number") {
    const used = usage(key);
    if (used + tokens > quota) {
      throw new Error("quota exceeded for key " + key + ": " + used + " + " + tokens + " > " + quota);
    }
  }
  state.calls = state.calls || [];
  state.calls.push({ key, model, tokens });
  return usage(key);
}

usage:
function usage(key) {
  const calls = state.calls || [];
  let total = 0;
  for (let i = 0; i < calls.length; i++) {
    if (calls[i].key === key) {
      total += calls[i].tokens;
    }
  }
  return total;
}

set_price:
function set_price(model, cents_per_1k_tokens) {
  state.prices = state.prices || {};
  state.prices[model] = cents_per_1k_tokens;
  return state.prices[model];
}

cost:
function cost(key) {
  const calls = state.calls || [];
  const prices = state.prices || {};
  let cents = 0;
  for (let i = 0; i < calls.length; i++) {
    if (calls[i].key === key) {
      const price = prices[calls[i].model];
      if (typeof price === "number") {
        cents += calls[i].tokens * price / 1000;
      }
    }
  }
  return Math.round(cents) / 100;
}

set_quota:
function set_quota(key, tokens) {
  if (typeof tokens !== "number" || !isFinite(tokens) || tokens < 0 || tokens % 1 !== 0) {
    throw new Error("quota must be a whole number of tokens, zero or more");
  }
  if (usage(key) > tokens) {
    throw new Error("key " + key + " has already used more than " + tokens + " tokens");
  }
  state.quotas = state.quotas || {};
  state.quotas[key] = tokens;
  return state.quotas[key];
}

top_spender:
function top_spender() {
  const calls = state.calls || [];
  const keys = [];
  for (let i = 0; i < calls.length; i++) {
    if (keys.indexOf(calls[i].key) === -1) {
      keys.push(calls[i].key);
    }
  }
  if (keys.length === 0) {
    return null;
  }
  keys.sort();
  let best = keys[0];
  let bestCost = cost(best);
  for (let i = 1; i < keys.length; i++) {
    const c = cost(keys[i]);
    if (c > bestCost) {
      best = keys[i];
      bestCost = c;
    }
  }
  return best;
}
